CREATE TABLE usage_segments (segment_id TEXT PRIMARY KEY, segment_name TEXT NOT NULL UNIQUE, policycenter_segment_code TEXT NOT NULL UNIQUE, technology_cost_center_label TEXT NOT NULL UNIQUE);

CREATE TABLE shared_service_pools (service_pool_id TEXT PRIMARY KEY, service_pool_name TEXT NOT NULL UNIQUE, pool_amount_usd INTEGER NOT NULL CHECK (pool_amount_usd >= 0), policy_driver_weight INTEGER NOT NULL CHECK (policy_driver_weight >= 0), system_usage_driver_weight INTEGER NOT NULL CHECK (system_usage_driver_weight >= 0), allocation_scope TEXT NOT NULL CHECK (allocation_scope IN ('ALL_SHARED_SERVICES','CLAIM_HANDLING','PREMIUM_ONLY')), eligible_for_abc INTEGER NOT NULL CHECK (eligible_for_abc IN (0,1)));

CREATE TABLE monthly_policy_system_usage (usage_id TEXT PRIMARY KEY, segment_id TEXT NOT NULL, service_pool_id TEXT NOT NULL, usage_month TEXT NOT NULL CHECK (length(usage_month) = 10), source_platform TEXT NOT NULL CHECK (source_platform IN ('PolicyCenter','ServiceNow','InvestmentPlatform','SeparatelyBilledApp')), in_force_policy_equivalents INTEGER NOT NULL CHECK (in_force_policy_equivalents >= 0), system_usage_units INTEGER NOT NULL CHECK (system_usage_units >= 0), eligible_for_shared_pool INTEGER NOT NULL CHECK (eligible_for_shared_pool IN (0,1)), source_record_status TEXT NOT NULL CHECK (source_record_status IN ('POSTED','RECONCILIATION_ONLY')), FOREIGN KEY (segment_id) REFERENCES usage_segments(segment_id), FOREIGN KEY (service_pool_id) REFERENCES shared_service_pools(service_pool_id), UNIQUE (segment_id, service_pool_id, usage_month, source_platform));